/// Return the Bidi_Class for a code point.
pub fn bidi_class(cp: u32) -> BidiClass {
    // Binary search on BIDI_CLASS_RANGES
    let mut lo: usize = 0;
    let mut hi: usize = BIDI_CLASS_RANGES.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let (start, end, _) = BIDI_CLASS_RANGES[mid];
        if cp < start {
            hi = mid;
        } else if cp > end {
            lo = mid + 1;
        } else {
            return BIDI_CLASS_RANGES[mid].2;
        }
    }
    BidiClass::L
}

