/// Return the matching closing bracket for an opening bracket, if any.
pub fn bracket_pair(cp: u32) -> Option<u32> {
    let mut lo: usize = 0;
    let mut hi: usize = BRACKET_PAIRS.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let (open, _) = BRACKET_PAIRS[mid];
        if cp < open {
            hi = mid;
        } else if cp > open {
            lo = mid + 1;
        } else {
            return Some(BRACKET_PAIRS[mid].1);
        }
    }
    None
}

