/// Check if a code point is a closing bracket.
pub fn is_closing_bracket(cp: u32) -> bool {
    let mut lo: usize = 0;
    let mut hi: usize = CLOSING_BRACKETS.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let (start, end) = CLOSING_BRACKETS[mid];
        if cp < start {
            hi = mid;
        } else if cp > end {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

