/// Return the matching opening bracket for a closing bracket, if any.
pub fn opening_bracket_for(cp: u32) -> Option<u32> {
    let mut lo: usize = 0;
    let mut hi: usize = CLOSE_TO_OPEN.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let (close, _) = CLOSE_TO_OPEN[mid];
        if cp < close {
            hi = mid;
        } else if cp > close {
            lo = mid + 1;
        } else {
            return Some(CLOSE_TO_OPEN[mid].1);
        }
    }
    None
}

